import { FC, HTMLAttributes, useState } from 'react';

import { Button, Flex, Typography } from 'antd';
import cn from 'classnames';

import SendIcon from 'assets/images/icons/send.svg?react';
import { useBrand } from 'entities/Brand/hooks/useBrand';
import { useBrandSlice } from 'entities/Brand/hooks/useBrandSlice';
import { MOCK_IPost } from 'shared/consts/MOCK_FOR_CATALOG';
import { LikeBtn } from 'shared/ui';

import styles from './CatalogPostCard.module.scss';

interface ICatalogPostCardProps extends HTMLAttributes<HTMLDivElement> {
	isShortView?: boolean;
	post: MOCK_IPost;
}

export const CatalogPostCard: FC<ICatalogPostCardProps> = ({ className, isShortView, post, ...props }) => {
	const { description, image, isLiked, name } = post;
	const [expanded, setExpanded] = useState(false);

	const { contextHolder, deleteFromCollection, handleSendClick, t } = useBrand();
	const { setIsOpenSaveToCollectionsDrawer, setIsOpenDetailsPopup, setPost } = useBrandSlice();

	const addToCollection = () => {
		setPost(post); //TODO: ask how to
		setIsOpenSaveToCollectionsDrawer(true);
	};

	const handleLikeClick = () => {
		isLiked ? deleteFromCollection() : addToCollection();
	};

	const handleDetailsClick = () => {
		// TODO:
		setPost(post);
		setIsOpenDetailsPopup(true);
	};

	return (
		<Flex
			gap={4}
			vertical
			{...props}
			className={cn(className, styles.catalogPostCard, !isShortView && styles.catalogPostCard__full)}>
			{contextHolder}
			<Flex className={styles.catalogPostCard__header}>
				<img className={styles.catalogPostCard__image} src={image} alt={name} />
				{!isShortView && (
					<Button className={styles.catalogPostCard__like} onClick={handleLikeClick} type={'text'}>
						<LikeBtn isLiked={isLiked} />
					</Button>
				)}
				{/*<PostTag className={styles.catalogPostCard__tag} icon={postTypeMap[type].icon}>*/}
				{/*	{postTypeMap[type].text}*/}
				{/*</PostTag>*/}
			</Flex>

			<Typography.Paragraph
				className={styles.catalogPostCard__lineClamp}
				ellipsis={{
					rows: 4,
					...(!isShortView && {
						expandable: 'collapsible',
						expanded,
						onExpand: (_, info) => setExpanded(info.expanded),
					}),
				}}>
				{description}
			</Typography.Paragraph>

			{!isShortView && (
				<Flex gap={4}>
					<Button style={{ flexShrink: 0 }} icon={<SendIcon />} onClick={handleSendClick} />
					<Button onClick={handleDetailsClick} block>
						{t('Детали')}
					</Button>
				</Flex>
			)}
		</Flex>
	);
};
